function switchGap(mask) {
  const isOn = (position) => Math.floor(mask / 2 ** position) % 2 === 1;
  let best = 0;
  for (let low = 0; low < 31; low++) {
    for (let high = low + 1; high < 31; high++) {
      if (!isOn(low) || !isOn(high)) continue;
      let neighbours = true;
      for (let between = low + 1; between < high; between++) {
        if (isOn(between)) neighbours = false;
      }
      if (neighbours) best = Math.max(best, high - low);
    }
  }
  return best;
}

function switchGap(mask) {
  let previous = -1;
  let best = 0;
  for (let position = 0; position < 31; position++) {
    if (Math.floor(mask / 2 ** position) % 2 === 1) {
      if (previous >= 0) best = Math.max(best, position - previous);
      previous = position;
    }
  }
  return best;
}

