function switchGap(mask) {
  let remaining = mask;
  let previous = -1;
  let best = 0;
  while (remaining > 0) {
    const lowest = remaining & -remaining;
    const position = 31 - Math.clz32(lowest);
    if (previous >= 0) best = Math.max(best, position - previous);
    previous = position;
    remaining &= remaining - 1;
  }
  return best;
}
